public class InstanceService {

    private static final int PING_TIMEOUT_MS = 5000;

    private final InstanceMapper instanceMapper;

    public InstanceService(InstanceMapper instanceMapper) {
        this.instanceMapper = instanceMapper;
    }

    public Instance createInstance(CreateInstanceRequest request, User currentUser) {
        Instance instance = new Instance();
        instance.setName(request.getName());
        instance.setDbType(request.getDbType());
        instance.setHost(request.getHost());
        instance.setPort(request.getPort());
        instance.setSchemaName(request.getSchemaName());
        instance.setAccount(request.getAccount());
        instance.setPassword(request.getPassword());
        instance.setGroupId(request.getGroupId());
        instance.setStatus("CREATED");
        instance.setOwnerId(currentUser.getId());
        LocalDateTime now = LocalDateTime.now();
        instance.setCreatedAt(now);
        instance.setUpdatedAt(now);
        instanceMapper.insert(instance);
        return instance;
    }

    public Instance getInstance(Long id, User currentUser) {
        Instance instance = instanceMapper.findById(id);
        if (instance == null || !canAccess(instance, currentUser)) {
            return null;
        }
        return instance;
    }

    public List<Instance> listInstances(User currentUser, String dbType, Long groupId) {
        boolean isAdmin = "ADMIN".equals(currentUser.getRole());
        return instanceMapper.findByFilters(currentUser.getId(), dbType, groupId, isAdmin);
    }

    public Instance updateInstance(Long id, UpdateInstanceRequest request, User currentUser) {
        Instance instance = getInstance(id, currentUser);
        if (instance == null) {
            return null;
        }
        if (request.getName() != null) {
            instance.setName(request.getName());
        }
        if (request.getHost() != null) {
            instance.setHost(request.getHost());
        }
        if (request.getPort() != null) {
            instance.setPort(request.getPort());
        }
        if (request.getSchemaName() != null) {
            instance.setSchemaName(request.getSchemaName());
        }
        if (request.getAccount() != null) {
            instance.setAccount(request.getAccount());
        }
        if (request.getPassword() != null) {
            instance.setPassword(request.getPassword());
        }
        if (request.getGroupId() != null) {
            instance.setGroupId(request.getGroupId());
        }
        instance.setUpdatedAt(LocalDateTime.now());
        instanceMapper.update(instance);
        return instance;
    }

    public String deleteInstance(Long id, User currentUser) {
        Instance instance = getInstance(id, currentUser);
        if (instance == null) {
            return "NOT_FOUND";
        }
        instanceMapper.deleteById(id);
        return "OK";
    }

    public Map<String, Object> pingInstance(Instance instance) {
        Map<String, Object> result = new HashMap<>();
        String dbType = instance.getDbType();
        if ("MYSQL".equals(dbType) || "REDIS".equals(dbType)) {
            pingTcp(instance, result);
        } else if ("OSS".equals(dbType)) {
            pingOss(instance, result);
        } else {
            result.put("reachable", false);
            result.put("latencyMs", null);
            result.put("detail", "不支持的实例类型");
        }
        return result;
    }

    private boolean canAccess(Instance instance, User currentUser) {
        return "ADMIN".equals(currentUser.getRole()) || instance.getOwnerId().equals(currentUser.getId());
    }

    private void pingTcp(Instance instance, Map<String, Object> result) {
        if (instance.getHost() == null || instance.getPort() == null) {
            result.put("reachable", false);
            result.put("latencyMs", null);
            result.put("detail", "主机或端口为空");
            return;
        }
        long start = System.currentTimeMillis();
        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(instance.getHost(), instance.getPort()), PING_TIMEOUT_MS);
            result.put("reachable", true);
            result.put("latencyMs", System.currentTimeMillis() - start);
            result.put("detail", "连接成功");
        } catch (Exception e) {
            result.put("reachable", false);
            result.put("latencyMs", null);
            result.put("detail", "连接超时");
        }
    }

    private void pingOss(Instance instance, Map<String, Object> result) {
        String resource = instance.getSchemaName() == null ? "" : instance.getSchemaName();
        String urlText = "http://" + instance.getHost() + "/" + resource;
        long start = System.currentTimeMillis();
        HttpURLConnection connection = null;
        try {
            URL url = new URL(urlText);
            // SSRF guard: must run before openConnection so no request reaches internal targets
            if (isForbiddenTarget(url.getHost())) {
                result.put("reachable", false);
                result.put("latencyMs", null);
                result.put("detail", "目标地址为内网或保留地址，禁止访问");
                return;
            }
            connection = (HttpURLConnection) url.openConnection();
            connection.setConnectTimeout(PING_TIMEOUT_MS);
            connection.setReadTimeout(PING_TIMEOUT_MS);
            connection.setRequestMethod("GET");
            connection.setInstanceFollowRedirects(false);
            int statusCode = connection.getResponseCode();
            result.put("reachable", true);
            result.put("latencyMs", System.currentTimeMillis() - start);
            result.put("detail", "连接成功，状态码: " + statusCode);
        } catch (Exception e) {
            result.put("reachable", false);
            result.put("latencyMs", null);
            result.put("detail", "连接超时");
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private boolean isForbiddenTarget(String host) throws UnknownHostException {
        if (host == null || host.isEmpty()) {
            return true;
        }
        for (InetAddress address : InetAddress.getAllByName(host)) {
            if (isPrivateOrReserved(address)) {
                return true;
            }
        }
        return false;
    }

    private boolean isPrivateOrReserved(InetAddress address) {
        if (address.isLoopbackAddress() || address.isAnyLocalAddress() || address.isLinkLocalAddress()
                || address.isSiteLocalAddress() || address.isMulticastAddress()) {
            return true;
        }
        byte[] bytes = address.getAddress();
        if (bytes.length == 16 && (bytes[0] & 0xFE) == 0xFC) {
            // IPv6 unique-local fc00::/7
            return true;
        }
        if (bytes.length == 4) {
            int b0 = bytes[0] & 0xFF;
            int b1 = bytes[1] & 0xFF;
            if (b0 == 100 && b1 >= 64 && b1 <= 127) {
                // 100.64.0.0/10 carrier-grade NAT
                return true;
            }
            if (b0 == 192 && b1 == 0 && (bytes[2] & 0xFF) == 0) {
                // 192.0.0.0/24 IETF protocol assignments
                return true;
            }
            if (b0 == 198 && (b1 == 18 || b1 == 19)) {
                // 198.18.0.0/15 benchmarking
                return true;
            }
            if (b0 >= 240) {
                // 240.0.0.0/4 reserved incl. broadcast
                return true;
            }
        }
        return false;
    }
