import javax.crypto.Mac;
import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.security.Key;
import java.util.Base64;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.Map;

/** Minimal functional stand-in for the jjwt 0.11 API surface used by the app (HS256 only). */
public final class Jwts {
    private Jwts() {}

    private static final Base64.Encoder B64E = Base64.getUrlEncoder().withoutPadding();
    private static final Base64.Decoder B64D = Base64.getUrlDecoder();

    public static JwtBuilder builder() {
        return new JwtBuilder();
    }

    public static JwtParserBuilder parserBuilder() {
        return new JwtParserBuilder();
    }

    private static byte[] hmac(Key key, byte[] data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(key);
            return mac.doFinal(data);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private static String jsonEscape(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    public static final class JwtBuilder {
        private final Map<String, Object> claims = new LinkedHashMap<>();
        private Key key;

        public JwtBuilder setSubject(String subject) {
            claims.put("sub", subject);
            return this;
        }

        public JwtBuilder claim(String name, Object value) {
            claims.put(name, value);
            return this;
        }

        public JwtBuilder setIssuedAt(Date date) {
            claims.put("iat", date.getTime() / 1000);
            return this;
        }

        public JwtBuilder setExpiration(Date date) {
            claims.put("exp", date.getTime() / 1000);
            return this;
        }

        public JwtBuilder signWith(Key key, SignatureAlgorithm alg) {
            this.key = key;
            return this;
        }

        public String compact() {
            StringBuilder body = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, Object> e : claims.entrySet()) {
                if (!first) body.append(',');
                first = false;
                body.append('"').append(jsonEscape(e.getKey())).append("\":");
                if (e.getValue() instanceof Number) {
                    body.append(e.getValue());
                } else {
                    body.append('"').append(jsonEscape(String.valueOf(e.getValue()))).append('"');
                }
            }
            body.append('}');
            String header = B64E.encodeToString("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes(StandardCharsets.UTF_8));
            String payload = B64E.encodeToString(body.toString().getBytes(StandardCharsets.UTF_8));
            String signingInput = header + "." + payload;
            String sig = B64E.encodeToString(hmac(key, signingInput.getBytes(StandardCharsets.UTF_8)));
            return signingInput + "." + sig;
        }
    }

    public static final class JwtParserBuilder {
        private Key key;

        public JwtParserBuilder setSigningKey(Key key) {
            this.key = key;
            return this;
        }

        public JwtParser build() {
            return new JwtParser(key);
        }
    }

    public static final class JwtParser {
        private final Key key;

        JwtParser(Key key) {
            this.key = key;
        }

        public Jws parseClaimsJws(String token) {
            String[] parts = token.split("\\.");
            if (parts.length != 3) {
                throw new IllegalArgumentException("malformed token");
            }
            String signingInput = parts[0] + "." + parts[1];
            String expected = B64E.encodeToString(hmac(key, signingInput.getBytes(StandardCharsets.UTF_8)));
            if (!expected.equals(parts[2])) {
                throw new SecurityException("invalid signature");
            }
            String json = new String(B64D.decode(parts[1]), StandardCharsets.UTF_8);
            String sub = extract(json, "sub");
            Long exp = extractLong(json, "exp");
            if (exp != null && exp * 1000 < System.currentTimeMillis()) {
                throw new IllegalStateException("token ***");
            }
            return new Jws(new Claims(sub));
        }

        private static String extract(String json, String field) {
            String needle = "\"" + field + "\":\"";
            int i = json.indexOf(needle);
            if (i < 0) return null;
            int start = i + needle.length();
            StringBuilder sb = new StringBuilder();
            for (int p = start; p < json.length(); p++) {
                char c = json.charAt(p);
                if (c == '\\' && p + 1 < json.length()) {
                    sb.append(json.charAt(++p));
                } else if (c == '"') {
                    break;
                } else {
                    sb.append(c);
                }
            }
            return sb.toString();
        }

        private static Long extractLong(String json, String field) {
            String needle = "\"" + field + "\":";
            int i = json.indexOf(needle);
            if (i < 0) return null;
            int start = i + needle.length();
            int end = start;
            while (end < json.length() && (Character.isDigit(json.charAt(end)) || json.charAt(end) == '-')) end++;
            if (end == start) return null;
            return Long.parseLong(json.substring(start, end));
        }
    }

    public static final class Jws {
        private final Claims claims;

        Jws(Claims claims) {
            this.claims = claims;
        }

        public Claims getBody() {
            return claims;
        }
    }
}
